-- October Special 2026 — starting data
-- Paste into Supabase → SQL Editor AFTER schema.sql and run.
-- Safe to run again: it refreshes the course cards and guides (until a round has scores),
-- and leaves dates, tee times, handicaps and anything else you've set alone.

insert into tournaments (slug, name, subtitle, organiser_player_id, start_date, theme, tone)
values ('october-special-2026', 'The October Special', 'Seven rounds. Two men. 360 points.', 'oisin', '2026-10-08', 'clubhouse', 'broadsheet')
on conflict (slug) do nothing;

insert into players (id, tournament_id, name, sort)
select p.id, t.id, p.name, p.sort
from tournaments t,
  (values ('oisin', 'Oisin', 1), ('neil', 'Neil', 2)) as p(id, name, sort)
where t.slug = 'october-special-2026'
on conflict (id) do nothing;

insert into rounds (tournament_id, number, course_slug, course_name, course_location, course_blurb, course_guide, lat, lon, tee, format, full_points, shots, holes, scorer_id)
select t.id, 1, 'local:druids-heath', 'Druids Heath', 'Newtownmountkennedy, Co. Wicklow', 'Pat Ruddy''s 2003 course at the Druids Glen resort: heathland with links-like touches, gorse, deep bunkers, lakes and sea breezes, with views of the mountains and the Irish Sea.', '{"overview":"Druids Heath was designed by Pat Ruddy and opened in 2003 as the second course at the Druids Glen resort near Newtownmountkennedy, Co. Wicklow. It is a mix of heathland and parkland with links-like elements, with gorse-lined rough, plentiful and often deep bunkers, several lakes and views of the mountains and the Irish Sea. Wide, rolling fairways and downhill tee shots are a feature, and sea breezes are a constant factor in how it plays. It hosted the 2006 Irish PGA Championship. The resort''s published layout is par 71.","signature":"The 12th, a long par 4 and stroke index 1, is the hole the resort calls one of the great par 4s in Irish golf; the drive must thread between gorse and hillsides. The par-3 14th, the ''quarry hole'', is played to a green set in an old rock quarry surrounded by rock and gorse.","holes":{"1":"Par 4, dogleg left to right. Keep the tee shot tight to the right side of the fairway; a fairway bunker on the left catches drives.","2":"Downhill risk-reward par 5 with a wide fairway. Two lakes front a small green.","3":"Par 3 protected by water, a pond running from tee to the left side of the green. A slope disguised by the right-hand bunker can help the tee shot.","4":"Short par 5 that looks more daunting than it is. Gorse and bunkers to avoid; keep the tee shot to the right side of the fairway.","5":"Uphill par 3. Take at least one more club, two into the wind.","6":"Par 4 whose fairway narrows the further you go. Avoid the fairway bunkers.","7":"Par 4, dogleg left with a blind tee shot that sets up to mislead; the line is on the left. Long hitters can cut the corner past bunkers.","8":"Short par 4 to an elevated green. Best to lay up to a favourite yardage for the second.","9":"Par 4 with a bunker in the middle of the fairway, which longer hitters can carry.","10":"Long, straightforward par 4 where missing the fairway is heavily punished.","11":"Picturesque, postage-stamp par 3. Short shots are punished; the green slopes from right to left.","12":"Stroke index 1. Long par 4: drive between a left bunker and a right-hand tree, through gorse and hillsides. Downslope helps; misses left, right or short leave a scramble.","13":"Picturesque medium-length par 4. Gorse hillside left off the tee, but keep the drive tight to the left; water right and in front of the green.","14":"The ''quarry hole'': short par 3 to a green in an old rock quarry, surrounded by rock and gorse. Club selection vital; do not be short.","15":"Short, uphill risk-reward par 5, the only par 5 on the back nine. Favour the left: tall trees block from the right. Hidden bunkers.","16":"Downhill par 4 whose fairway narrows the further you go. Avoid the bunkers left of the fairway.","17":"Testing par 4. Drive must avoid the bunkers, leaving an uphill second shot.","18":"Par 4 finish that looks harder than it is. Narrow opening to the fairway, bunkers, and an elevated green."}}'::jsonb, 53.075, -6.085, 'White', 'stableford', 20,
  '{"oisin":0,"neil":0}'::jsonb, '[{"number":1,"par":4,"si":2,"yards":420},{"number":2,"par":5,"si":8,"yards":540},{"number":3,"par":3,"si":14,"yards":185},{"number":4,"par":5,"si":18,"yards":503},{"number":5,"par":3,"si":16,"yards":178},{"number":6,"par":4,"si":6,"yards":454},{"number":7,"par":4,"si":4,"yards":408},{"number":8,"par":4,"si":12,"yards":351},{"number":9,"par":4,"si":10,"yards":391},{"number":10,"par":4,"si":7,"yards":385},{"number":11,"par":3,"si":13,"yards":185},{"number":12,"par":4,"si":1,"yards":457},{"number":13,"par":4,"si":5,"yards":338},{"number":14,"par":3,"si":17,"yards":159},{"number":15,"par":5,"si":15,"yards":475},{"number":16,"par":4,"si":3,"yards":449},{"number":17,"par":4,"si":9,"yards":375},{"number":18,"par":4,"si":11,"yards":367}]'::jsonb, 'oisin'
from tournaments t where t.slug = 'october-special-2026'
on conflict (tournament_id, number) do update set
  course_slug = excluded.course_slug, course_name = excluded.course_name, course_location = excluded.course_location,
  course_blurb = excluded.course_blurb, course_guide = excluded.course_guide, lat = excluded.lat, lon = excluded.lon,
  tee = excluded.tee, holes = excluded.holes
where not exists (select 1 from hole_entries e where e.round_id = rounds.id);

insert into rounds (tournament_id, number, course_slug, course_name, course_location, course_blurb, course_guide, lat, lon, tee, format, full_points, shots, holes, scorer_id)
select t.id, 2, 'local:wicklow', 'Wicklow Golf Club', 'Wicklow Town, Co. Wicklow', 'A clifftop course above Wicklow town. Short on the card at par 71, but the wind off the sea does the defending.', '{"overview":"Wicklow Golf Club was founded in 1904 as a nine-hole course on the cliffs at Dunbur Head, just south of Wicklow town, and was extended to 18 holes to a design by Pat Ruddy and the late Tom Craddock in the early 1990s. It is a compact (about 90 acres) clifftop course on parkland-type soil with a links feel, tilting down towards the sea from the clubhouse, with views of the sea from every hole and of the Wicklow Mountains. Fairways roll and hang on slopes, there are blind shots and elevated greens, seven greens sit on or very close to the cliff edge, and exposure to wind makes greens hard to hit. It is hilly; buggies are widely recommended. Par 71.","signature":"The par-4 6th, nicknamed ''Pebble Beach'', asks for a tee shot carried over the cliffs and the Irish Sea to reach the fairway from the back tees. Three par 3s – the 7th, 11th and 17th – are played across Dunbur Glen.","holes":{"1":"Opening par 5 that tumbles downhill from the clubhouse towards the sea.","6":"Signature par 4, ''Pebble Beach''. From the back (blue) tees the drive must carry rugged cliffs and the Irish Sea, about 175-190 yards, to the fairway.","7":"Short par 3 played across Dunbur Glen. Quirky, eccentric green that can yield a birdie or a triple bogey.","11":"Par 3 played across Dunbur Glen.","17":"Par 3 played across Dunbur Glen."}}'::jsonb, 52.974, -6.031, 'Blue', 'stableford', 20,
  '{"oisin":0,"neil":0}'::jsonb, '[{"number":1,"par":5,"si":8,"yards":522},{"number":2,"par":4,"si":1,"yards":401},{"number":3,"par":4,"si":18,"yards":264},{"number":4,"par":4,"si":12,"yards":302},{"number":5,"par":4,"si":16,"yards":301},{"number":6,"par":4,"si":4,"yards":406},{"number":7,"par":3,"si":10,"yards":137},{"number":8,"par":4,"si":6,"yards":396},{"number":9,"par":3,"si":15,"yards":144},{"number":10,"par":4,"si":2,"yards":363},{"number":11,"par":3,"si":17,"yards":170},{"number":12,"par":4,"si":7,"yards":397},{"number":13,"par":4,"si":5,"yards":348},{"number":14,"par":5,"si":3,"yards":545},{"number":15,"par":4,"si":9,"yards":356},{"number":16,"par":5,"si":13,"yards":474},{"number":17,"par":3,"si":11,"yards":161},{"number":18,"par":4,"si":14,"yards":348}]'::jsonb, 'oisin'
from tournaments t where t.slug = 'october-special-2026'
