  course_blurb = excluded.course_blurb, course_guide = excluded.course_guide, lat = excluded.lat, lon = excluded.lon,
  tee = excluded.tee, holes = excluded.holes
where not exists (select 1 from hole_entries e where e.round_id = rounds.id);

insert into rounds (tournament_id, number, course_slug, course_name, course_location, course_blurb, course_guide, lat, lon, tee, format, full_points, shots, holes, scorer_id)
select t.id, 3, 'local:macreddin', 'Macreddin', 'Macreddin Village, Co. Wicklow', 'A Paddy Merrigan design in a secluded valley in the Wicklow hills, over 7,000 yards from the back. Water and elevation everywhere.', '{"overview":"Macreddin was Paul McGinley''s first course design and remains his only full course design in Ireland; work began in 2005, nine holes opened in September 2007 and the full 18 opened in summer 2008. It is a par-72 parkland course on about 160 acres stretching up both sides of the valley at Macreddin, beside the BrookLodge hotel, with gorse, tall pines and spruce and big elevation changes. The front nine is tree-lined and demanding; the back nine is shaped by the Macreddin and Ballycrean brooks. Many holes are doglegs and accuracy matters more than length. It is hilly with long walks from some greens to tees, so buggies are commonly recommended.","signature":"The par-4 12th (''McGinley''s''), stroke index 1 and the designer''s favourite, is played from a hugely elevated tee over the ravine of Ballycrean Brook. The par-3 4th (''Kite''s Nest'') drops to a green about 40 metres below the tee, and the 18th finishes with the brook criss-crossing the fairway.","holes":{"1":"''Cronawinna''. Generous fairway for the opening drive; the hole then turns left to a green set in its own vale.","2":"''Deer Run''. First of the tree-lined fairways. Par 5 turning right after the drive to a green nestled among pines and spruce.","3":"''Ballcoog''. Elevated tee with a panoramic view down the valley. Generous landing area, then a straightforward iron to a large green.","4":"''Kite''s Nest''. Long par 3 to a green about 40 metres below the tee; the ball hangs in the air a long time.","5":"''Furze & Pheasants''. Plays longer than its yardage, usually into the prevailing wind. Drive positioning is key to a straightforward second.","6":"''Druid''s Dell''. Short par 4; a long, accurate drive sets up a birdie chance.","7":"''Forager''s Way''. Par 3 from tees nestled in pines and spruce; medium iron to a well-guarded green.","8":"''Croghan''. Par 5, level for the first half, then turns right and runs downhill to a green in the valley.","9":"''The Bridle Path''. Par 4 flanked by woodland on the left. Tricky second shot to a green backed by the Macreddin stone bridge.","10":"''Above Ground''. Short, uphill par 4 with a narrow fairway; short iron to a small, well-guarded green. Mounding hides the lower part of the pin.","11":"''The Blue School''. Short uphill par 4. Stream left of the fairway, woodland right; accurate drive leaves a straightforward approach.","12":"''McGinley''s''. Stroke index 1. Dogleg par 4 from a hugely elevated tee; drive over Ballycrean Brook''s ravine, then a long iron between pines.","13":"''Hidden Valley''. Tree-lined par 5 playing downhill with the prevailing wind. Risk-reward second to a well-bunkered green.","14":"''The Crooked Birch''. Par 3 with a stream guarding the approach to a long green, allowing widely varying pin positions.","15":"''Coillte''. Last par 5. Densely tree-lined fairway curving right; a meandering stream comes into play for the second shot.","16":"''Pine Valley''. Longest par 4 on the course, carved through woodland; demands length and accuracy.","17":"''Kingfisher''. Downhill par 3; the brook runs across the front of a wide but shallow green.","18":"''Ballycrean''. Risk-reward par-4 finish: an island landing area with the Macreddin brook criss-crossing the fairway."}}'::jsonb, 52.898, -6.348, 'White', 'stroke', 20,
  '{"oisin":0,"neil":0}'::jsonb, '[{"number":1,"par":4,"si":6,"yards":363},{"number":2,"par":5,"si":8,"yards":513},{"number":3,"par":4,"si":10,"yards":396},{"number":4,"par":3,"si":16,"yards":173},{"number":5,"par":4,"si":4,"yards":402},{"number":6,"par":4,"si":18,"yards":299},{"number":7,"par":3,"si":14,"yards":177},{"number":8,"par":5,"si":12,"yards":564},{"number":9,"par":4,"si":2,"yards":412},{"number":10,"par":4,"si":13,"yards":302},{"number":11,"par":4,"si":17,"yards":292},{"number":12,"par":4,"si":1,"yards":398},{"number":13,"par":5,"si":11,"yards":499},{"number":14,"par":3,"si":15,"yards":162},{"number":15,"par":5,"si":5,"yards":514},{"number":16,"par":4,"si":3,"yards":451},{"number":17,"par":3,"si":9,"yards":165},{"number":18,"par":4,"si":7,"yards":411}]'::jsonb, 'oisin'
