insert into rounds (tournament_id, number, course_slug, course_name, course_location, course_blurb, course_guide, lat, lon, tee, format, full_points, shots, holes, scorer_id)
select t.id, 4, 'local:rathsallagh', 'Rathsallagh', 'Dunlavin, Co. Wicklow', 'Parkland on a historic estate on the Wicklow–Kildare border, designed by Peter McEvoy and Christy O''Connor Jnr. Mature trees, water and fast greens.', '{"overview":"Rathsallagh was designed by Peter McEvoy and Christy O''Connor Jnr and opened in 1994 on roughly 270 acres of rolling parkland on the Rathsallagh House estate near Dunlavin, Co. Wicklow. The course was built around the estate''s mature beech, oak and lime trees (reportedly not a tree was felled in construction), with burns, ditches, ponds and lakes bringing water into play on several holes. It is par 72, about 6,885 yards from the back tees and 6,483 from the whites, with around 45 well-placed bunkers and USGA-specification greens noted for their contours and tiers. The club closed in February 2015 and reopened under new ownership in June 2016. Tee-shot placement is the recurring theme: tree-lined doglegs and tiered greens punish the wrong side of the fairway.","signature":"The 10th, a long par-4 Index 1 squeezed between oak trees and a ditch on the left and a lake on the right, and the uphill 18th to a multi-tiered green are the holes reviewers single out as among the finest in Ireland. The downhill par-3 13th (134 yards from the whites) and the hazard-strewn par-5 6th are also widely praised.","holes":{"1":"Gentle, generous par 5 to open, designed to ease players into their rhythm; an early birdie chance.","2":"Dogleg par 4 through an avenue of trees. Tee-shot placement is key to seeing a green with a narrowing entrance and deep bunkers on both sides.","4":"Par 3 with plenty of trouble around it; one reviewer says it has wrecked many cards.","6":"Par 5 needing a draw around an oak wood left and a tree jutting into the fairway. Drain down the right; humpy green guarded by two lakes and bunkers short.","7":"Par 3 played across a pond to a green set against a backdrop of tall pines and mature trees.","8":"Short par 4 that runs straight then turns sharply, about 90 degrees. Water short and long of the green, a deep bunker and a narrow putting surface.","9":"Strong uphill par 4 that turns right to left, demanding an exacting iron approach to a sharply sloping two-tiered green.","10":"Index 1 par 4. Oaks and a ditch line the left, a large lake sits right. Pulled drives find water or rough; a push rules out reaching in two.","13":"Short downhill par 3 played from a high tee; very pretty, and rated by reviewers as one of the best short holes around.","16":"Par 5 that doglegs twice (a double dogleg).","18":"Long uphill par 4 finisher: out of bounds left, trouble right and a semi-blind approach to a heavily tiered green. Reviewers rate it one of Ireland''s toughest closing holes."}}'::jsonb, 53.035, -6.689, 'White', 'stableford', 20,
  '{"oisin":0,"neil":0}'::jsonb, '[{"number":1,"par":5,"si":13,"yards":506},{"number":2,"par":4,"si":2,"yards":436},{"number":3,"par":4,"si":15,"yards":367},{"number":4,"par":3,"si":11,"yards":158},{"number":5,"par":4,"si":9,"yards":373},{"number":6,"par":5,"si":6,"yards":490},{"number":7,"par":3,"si":17,"yards":177},{"number":8,"par":4,"si":4,"yards":351},{"number":9,"par":4,"si":7,"yards":370},{"number":10,"par":4,"si":1,"yards":438},{"number":11,"par":5,"si":10,"yards":510},{"number":12,"par":4,"si":12,"yards":355},{"number":13,"par":3,"si":18,"yards":134},{"number":14,"par":4,"si":14,"yards":332},{"number":15,"par":4,"si":8,"yards":374},{"number":16,"par":5,"si":5,"yards":516},{"number":17,"par":3,"si":16,"yards":170},{"number":18,"par":4,"si":3,"yards":426}]'::jsonb, 'oisin'
