insert into rounds (tournament_id, number, course_slug, course_name, course_location, course_blurb, course_guide, lat, lon, tee, format, full_points, shots, holes, scorer_id)
select t.id, 5, 'local:concra-wood', 'Concra Wood', 'Castleblayney, Co. Monaghan', 'A Christy O''Connor Jnr design wrapped around Lough Muckno. Big drumlin country, lakeside holes and one of the best newer courses in Ulster.', '{"overview":"Concra Wood was designed by Christy O''Connor Jnr with his uncle Christy O''Connor Snr and formally opened in 2008. It replaced Castleblayney Golf Club, a nine-holer founded in 1905, on a roughly 240-acre estate beside Lough Muckno. The lough borders the course on three sides and, according to Irish Golf Desk, comes into play on 11 holes, with the main water stretches at the 4th to 6th and the 12th to 16th. It is a big, spacious parkland layout of more than 7,000 yards from the championship tees, with significant elevation changes, elevated tees and holes that reveal themselves only from the tee. One reviewer raises concerns about playability at some times of year, and visitor comments recommend a buggy.","signature":"The par-5 4th is usually called the signature hole: a double dogleg that swings right, then runs along the lough and dips left to a narrow shoreside green. The 10th, with its plunging approach from an elevated fairway to a green overlooking the lough, and the lakeside par-5 13th (''Lough Muckno'') are the other standouts. The 16th''s tee shot over water also draws praise.","holes":{"1":"Par-5 opener (''Castleblaney'') offering an early scoring chance if the drive finds the fairway.","2":"Solid par 4; a controlled drive sets up a mid-iron approach.","3":"Shorter par 4 dropping quickly downhill and doglegging out towards the lough; the green is guarded by a pond. Rewards accurate positioning off the tee.","4":"Signature par 5, a double dogleg: narrow tee shot, fairway veers sharply right, runs beside the lough, then dips left to a narrow green just above the waterline.","5":"Testing par 4 needing both length and precision to reach in regulation; part of the 4th-6th stretch where Lough Muckno threatens.","6":"Par 3 calling for a precise strike; falls within the 4th-6th lakeside stretch.","7":"Par 4 where accuracy off the tee gives a good chance to attack the green.","9":"Longer par 3 demanding good distance control to avoid trouble.","10":"''Crossmaglen'': strong par 4 needing a good drive, then a spectacular approach from an elevated fairway plunging down to a green overlooking the lough.","11":"Par 4 offering birdie chances after a well-placed tee shot.","12":"Quality par 3 with the lake in play; club selection is key.","13":"''Lough Muckno'': par 5 with the lake in play and a tempting tiger line to cut the corner. Reaching in two is tough; the green is huge and deceptive.","14":"Shortest hole on the course, about 160 yards, rewarding precision over power; part of the lakeside 12th-16th stretch.","15":"Short par 5 whose tee shot cuts across a corner of the lake; a good chance to pick up a shot.","16":"Long par 4 doglegging right to left. The tee seems to sit in the lake, the drive carries water and the green is lakeside.","17":"Strong penultimate par 4 that tests consistency.","18":"Par-4 finisher (''Christy Jnr'') with the clubhouse towering above the green; needs focus and accuracy."}}'::jsonb, 54.105, -6.74, 'Black', 'match', 30,
  '{"oisin":0,"neil":0}'::jsonb, '[{"number":1,"par":5,"si":13,"yards":500},{"number":2,"par":4,"si":3,"yards":400},{"number":3,"par":4,"si":17,"yards":352},{"number":4,"par":5,"si":5,"yards":543},{"number":5,"par":4,"si":1,"yards":410},{"number":6,"par":3,"si":15,"yards":177},{"number":7,"par":4,"si":11,"yards":380},{"number":8,"par":4,"si":7,"yards":370},{"number":9,"par":3,"si":9,"yards":178},{"number":10,"par":4,"si":6,"yards":433},{"number":11,"par":4,"si":4,"yards":367},{"number":12,"par":3,"si":16,"yards":187},{"number":13,"par":5,"si":12,"yards":497},{"number":14,"par":3,"si":18,"yards":161},{"number":15,"par":5,"si":14,"yards":470},{"number":16,"par":4,"si":2,"yards":427},{"number":17,"par":4,"si":8,"yards":410},{"number":18,"par":4,"si":10,"yards":373}]'::jsonb, 'oisin'
