insert into rounds (tournament_id, number, course_slug, course_name, course_location, course_blurb, course_guide, lat, lon, tee, format, full_points, shots, holes, scorer_id)
select t.id, 6, 'local:slieve-russell', 'Slieve Russell', 'Ballyconnell, Co. Cavan', 'A big parkland championship course in the Cavan lakelands, with lakes and water in play and a stern run of par 4s.', '{"overview":"The championship course at Slieve Russell (now branded PGA National Ireland Slieve Russell) was designed by Paddy (Patrick) Merrigan and opened in 1992 on a 300-acre estate near Ballyconnell that includes about 50 acres of lakes. It is a parkland layout wrapped around the lakes and drumlins of west Cavan, par 72 and a little over 7,000 yards from the back tees, with roughly 100 bunkers and large, rolling greens that reviewers describe as fast and tricky to read. Water is most prominent on the 11th, 12th, 13th and 16th, and the quarry sand-and-gravel base gives it a reputation for good drainage. It has hosted the Irish PGA Championship (1996), the European Tour''s North West of Ireland Open (2001 and 2002) and the European Ladies'' Team Championship (July 2026).","signature":"The par-5 13th, ''Watergate'', is the best-known hole: a dogleg left whose drive carries Lough Rud, with the fairway hugging the water all the way to a green on the lake''s edge and an ''SR'' floral display beside it. The elevated par-3 7th (''Tee More''), the par-3 11th over water and the par-3 16th (''The Mourning Pond'') are also frequently singled out.","holes":{"1":"''Shannon Pot''. Opening par 4 that doglegs left to right, with a highly visible bunker at the elbow of the dogleg.","2":"''Aghavoher Leap''. Long par 4 with water in play: downhill drive over water to a narrow fairway, then an uphill approach over water to an elevated, well-protected green.","4":"''Wishing Well''. Short par 3 demanding accuracy and distance control; a multi-tiered green means finding the wrong plateau brings three-putts into play.","5":"''Feather Bed Lane''. Par 4 with a heavily undulating fairway and elevation changes; a single bunker guards the green.","7":"''Tee More''. Long par 3 played from an elevated tee, the green fully visible below and ringed by bunkers on all sides; wind judgement is key.","10":"''Swan Lake''. Par 4 snaking left to right, with bunkers at the elbow and an elevated, well-protected green.","11":"''Heron Haunt''. Par 3 played over water to a stage-like green; anything short finds water, and four bunkers surround the putting surface.","12":"''Risky Rud''. Difficult par 4 swinging right to left, with water down the entire left side; the green sits into the water with bunkering on the right.","13":"''Watergate''. Par-5 dogleg left: drive over Lough Rud, bite off as much as you dare. Fairway clings to the lake all the way to a waterside green; reachable in two.","16":"''The Mourning Pond''. Par 3 where water covers anything short; bunkers guard the other sides of the green.","17":"''Cranaghan Bend''. Par 4 doglegging left to right; tee-shot placement matters to set up the approach to an elevated green.","18":"''The Gap''. Strong closing par 5 with a meandering fairway that weaves left and right towards the green."}}'::jsonb, 54.112, -7.592, 'White', 'match', 30,
  '{"oisin":0,"neil":0}'::jsonb, '[{"number":1,"par":4,"si":10,"yards":397},{"number":2,"par":4,"si":1,"yards":403},{"number":3,"par":4,"si":6,"yards":371},{"number":4,"par":3,"si":16,"yards":151},{"number":5,"par":4,"si":3,"yards":410},{"number":6,"par":5,"si":18,"yards":485},{"number":7,"par":3,"si":8,"yards":200},{"number":8,"par":4,"si":14,"yards":329},{"number":9,"par":5,"si":12,"yards":509},{"number":10,"par":4,"si":2,"yards":393},{"number":11,"par":3,"si":11,"yards":173},{"number":12,"par":4,"si":4,"yards":415},{"number":13,"par":5,"si":9,"yards":494},{"number":14,"par":4,"si":17,"yards":346},{"number":15,"par":4,"si":5,"yards":410},{"number":16,"par":3,"si":7,"yards":156},{"number":17,"par":4,"si":15,"yards":376},{"number":18,"par":5,"si":13,"yards":512}]'::jsonb, 'oisin'
