where not exists (select 1 from hole_entries e where e.round_id = rounds.id);

insert into rounds (tournament_id, number, course_slug, course_name, course_location, course_blurb, course_guide, lat, lon, tee, format, full_points, shots, holes, scorer_id)
select t.id, 7, 'local:farnham-estate', 'Farnham Estate', 'Cavan Town, Co. Cavan', 'A Jeff Howes design through 1,300 acres of ancient woodland and lakes on the Farnham Estate. A fitting place for the 40-point finale.', '{"overview":"Farnham Estate''s course was designed by Jeff Howes, a Kilkenny-based Canadian architect (GolfPass also credits Jonathan Davison). Most sources say it opened in 2009. It is a par-72 parkland course spread over about 500 acres just outside Cavan town on the Killeshandra road, with two contrasting nines. The front nine runs over open, undulating meadow and the back nine climbs into dense, tighter woodland. A meandering stream and seven lakes bring water into play, the bunkers are described as large, flat-bottomed and natural-looking, and reviewers praise the greens. Several reviewers mention soft or wet fairways and long walks between some greens and tees, and buggies are recommended.","signature":"The 4th is generally regarded as the signature hole and is the designer''s own favourite: a stroke-index-1 par 4 needing a slight draw between two large oak trees to a green guarded by water. The 2nd (a downhill par 4 over a stream), the drivable par-4 14th, the tree-lined par-5 15th and the par-5 18th around the lake below the hotel are also often mentioned.","holes":{"1":"Opening par 4 with a very open, generous fairway and plenty of room left and right.","2":"Long par 4 from a high tee, downhill between trees left and rough slope right; approach crosses a stream/pond to a green in a glade. Avoid the right.","3":"Par 4 with water in play; how much of the water to take on is the strategic decision.","4":"Stroke index 1 and the designer''s favourite. Needs a slight draw between two large oaks; the well-guarded green has water behind and to the right, so approach from the left.","5":"Straightforward par 3 on the open front nine, described by one reviewer as the plainest hole on the course.","6":"Long par 5 with a tight landing area for the third shot.","7":"Par 4 with a large bunker hugging the left side; the fairway is generous to the right but narrows further on.","8":"Long par 3 with a stream just short of the green and a long bunker and rough to the right.","9":"Par 5 that plays shorter than its yardage; a good drive leaves little to reach the green.","10":"First hole of the woodland back nine: a short but tight par 4, followed by a steep walk uphill from behind the green.","13":"Par 4 up in the forest; wayward tee shots disappear deep into the trees, and deep rough and soft ground punish anything off line.","14":"Drivable short par 4 (stroke index 16) with a hard green to hit and numerous bunkers left and right.","15":"Three-shot par 5 down a narrow, tree-lined fairway sloping downhill; balls in the trees are rarely found. A reviewers'' favourite.","16":"Picturesque par 3 on the wooded back nine, cited by several golfers as a contender for signature hole.","18":"Par-5 finisher sweeping around a lake below the hotel; tee shot carries water; taking on more water gives a chance to get home in two. Overlooked by the clubhouse terrace."}}'::jsonb, 54, -7.405, 'White', 'stroke', 40,
  '{"oisin":0,"neil":0}'::jsonb, '[{"number":1,"par":4,"si":15,"yards":347},{"number":2,"par":4,"si":11,"yards":356},{"number":3,"par":4,"si":5,"yards":337},{"number":4,"par":4,"si":1,"yards":399},{"number":5,"par":3,"si":7,"yards":162},{"number":6,"par":5,"si":17,"yards":509},{"number":7,"par":4,"si":9,"yards":358},{"number":8,"par":3,"si":3,"yards":182},{"number":9,"par":5,"si":13,"yards":433},{"number":10,"par":4,"si":16,"yards":318},{"number":11,"par":4,"si":12,"yards":402},{"number":12,"par":3,"si":6,"yards":171},{"number":13,"par":4,"si":2,"yards":380},{"number":14,"par":4,"si":8,"yards":261},{"number":15,"par":5,"si":18,"yards":514},{"number":16,"par":3,"si":10,"yards":153},{"number":17,"par":4,"si":4,"yards":367},{"number":18,"par":5,"si":14,"yards":452}]'::jsonb, 'oisin'
from tournaments t where t.slug = 'october-special-2026'
on conflict (tournament_id, number) do update set
  course_slug = excluded.course_slug, course_name = excluded.course_name, course_location = excluded.course_location,
  course_blurb = excluded.course_blurb, course_guide = excluded.course_guide, lat = excluded.lat, lon = excluded.lon,
  tee = excluded.tee, holes = excluded.holes
where not exists (select 1 from hole_entries e where e.round_id = rounds.id);
